<template>
  <div class="profile">

    <table class="" v-if="user">

      <template v-if="user">

        <!-- Employee properties -->
        <tr>
          <th class="first_row" colspan="1000">個人情報 / Personal information</th>
        </tr>

        <tr>
          <td>ID</td>
          <td>{{user.identity.low}}</td>
        </tr>

        <tr
          v-for="(val, key) in user.properties"
          v-bind:key="key">
          <td v-if="key !== 'password_hashed'">{{key}}</td>
          <td v-if="key !== 'password_hashed'">{{val}}</td>
        </tr>

      </template>

      <template v-if="groups.length > 0">

        <!-- Groups -->
        <tr>
          <th class="" colspan="1000">Groups</th>
        </tr>

        <tr
          v-for="(group, index) in groups"
          v-bind:key="`group_${index}`">
          <td>{{group.labels[0]}}</td>
          <td>{{group.properties.name}}</td>

          <td>
            <button type="button" v-on:click="leave_group(group)">Leave</button>
          </td>

        </tr>
      </template>

      <!-- Option to join a group -->
      <tr>
        <td>Join a group</td>
        <td>
          <button
            type="button"
            v-on:click="group_selection_modal_open = true">
            Open group selector
          </button>
        </td>
      </tr>

      <template v-if="workplaces.length > 0">

        <!-- Workplaces-->
        <tr>
          <th class="" colspan="1000">Workplaces</th>
        </tr>

        <tr
          v-for="workplace in workplaces"
          v-bind:key="workplace.identity.low">
          <!-- using labels 0 is not robust -->
          <td>{{workplace.labels[0]}}</td>
          <td>{{workplace.properties.name}}</td>

          <td>
            <button type="button" v-on:click="leave_workplace(workplace)">Leave</button>
          </td>

        </tr>





        <!-- Option to add a workplace -->
        <tr v-if="all_workplaces.length > 0">
          <td>Add workplace</td>
          <td>
            <select ref="new_workplace_select" >
              <option
                v-for="workplace in all_workplaces"
                v-bind:key="workplace.identity.low"
                v-bind:value="workplace.identity.low">{{workplace.properties.name}}</option>
            </select>
          </td>
          <td>
            <button type="button" v-on:click="join_workplace()">Join</button>
          </td>
        </tr>
      </template>

    </table>

    <Modal
      v-bind:open="group_selection_modal_open"
      v-on:close="group_selection_modal_open = false">
      <GroupPicker
        apiUrl="http://172.16.98.151:8097"
        v-on:selection="join_group($event)"/>
    </Modal>



  </div>
</template>

<script>
// @ is an alias to /src
import Modal from '@moreillon/vue_modal'
import GroupPicker from '@moreillon/vue_group_picker'

export default {
  name: 'MyProfile',
  components: {
    Modal,
    GroupPicker,
  },
  data(){
    return {
      user: null,
      groups: [],
      workplaces: [],

      all_workplaces: [],
      group_selection_modal_open: false,
    }
  },
  mounted(){
    this.get_employee_information()
    // Get all workplaces for <select> to join a new workplace
    this.get_all_workplaces()
  },
  methods: {

    get_employee_information(){
      this.axios.post(`${process.env.VUE_APP_EMPLOYEE_MANAGER_URL}/get_employee`, {
        employee_id: this.$route.query.id,
      })
      .then(response => {
        this.user = response.data
        this.get_groups()
        this.get_workplaces()
      })
      .catch(error => alert(error))
    },

    get_groups(){
      this.axios.post(`${process.env.VUE_APP_EMPLOYEE_MANAGER_URL}/get_groups_of_employee`, {
        employee_id: this.$route.query.id,
      })
      .then(response => {
        this.groups.splice(0,this.groups.length)
        response.data.forEach((record) => {
          let group = record._fields[record._fieldLookup['group']]
          this.groups.push(group)
        });

      })
      .catch(error => alert(error))
    },
    get_workplaces(){
      this.axios.post(`${process.env.VUE_APP_EMPLOYEE_MANAGER_URL}/get_workplaces_of_employee`, {
        employee_id: this.$route.query.id,
      })
      .then(response => {
        this.workplaces.splice(0,this.workplaces.length)
        response.data.forEach((record) => {
          let workplace = record._fields[record._fieldLookup['workplace']]
          this.workplaces.push(workplace)
        });

      })
      .catch(error => alert(error))
    },

    join_workplace(){
      this.axios.post(`${process.env.VUE_APP_EMPLOYEE_MANAGER_URL}/join_workplace`, {
        employee_id: this.$route.query.id,
        workplace_id: this.$refs.new_workplace_select.value
      })
      .then(response => {
        this.workplaces.splice(0,this.workplaces.length)
        response.data.forEach((record) => {
          let workplace = record._fields[record._fieldLookup['workplace']]
          this.workplaces.push(workplace)
        });
        this.get_workplaces()

      })
      .catch(error => {
        if(error.response) alert(error.response.data)
        else alert(error)
      })
    },

    leave_workplace(workplace){
      if(confirm(`Leave ${workplace.properties.name}`)){
        this.axios.post(`${process.env.VUE_APP_EMPLOYEE_MANAGER_URL}/leave_workplace`, {
          employee_id: this.$route.query.id,
          workplace_id: workplace.identity.low
        })
        .then( () => { this.get_workplaces() })
        .catch(error => {
          if(error.response) alert(error.response.data)
          else alert(error)
        })
      }
    },

    join_group(group){
      if(confirm(`Join ${group.properties.name}?`)){
        this.axios.post(`${process.env.VUE_APP_EMPLOYEE_MANAGER_URL}/join_group`, {
          employee_id: this.$route.query.id,
          group_id: group.identity.low
        })
        .then( () => { this.get_groups() })
        .catch(error => {
          if(error.response) alert(error.response.data)
          else alert(error)
        })
      }
    },

    leave_group(group){
      if(confirm(`Leave ${group.properties.name}?`)){
        this.axios.post(`${process.env.VUE_APP_EMPLOYEE_MANAGER_URL}/leave_group`, {
          employee_id: this.$route.query.id,
          group_id: group.identity.low
        })
        .then( () => { this.get_groups() })
        .catch(error => {
          if(error.response) alert(error.response.data)
          else alert(error)
        })
      }
    },

    get_all_workplaces(){
      this.axios.get(`${process.env.VUE_APP_EMPLOYEE_MANAGER_URL}/all_workplaces`)
      .then(response => {
        this.all_workplaces.splice(0,this.all_workplaces.length)
        response.data.forEach((record) => {
          let workplace = record._fields[record._fieldLookup['workplace']]
          this.all_workplaces.push(workplace)

        });
      })
      .catch(error =>console.log(error));
    },

  }
}
</script>

<style scoped>

table {
  width: 100%;
  border-collapse: collapse;
}

tr:not(:last-child) {
  border-bottom: 1px solid #dddddd;
}

td, th {
  padding: 2px;
}

th:not(.first_row) {
  padding-top: 25px;
}

</style>
